  ('super-potion', 'Super Potion', 'Restores 50 HP to one Pokémon.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/items/super-potion.png', 35, '{"kind":"heal","amount":50}'::jsonb, true, 1, null, null, false),
